INSERT INTO tblRestaurant (id,name,address,phone,email,description) SELECT 1,'RestMan','','','','' WHERE NOT EXISTS (SELECT 1 FROM tblRestaurant WHERE id=1);
INSERT INTO tblSize (name) SELECT 'M' WHERE NOT EXISTS (SELECT 1 FROM tblSize WHERE name='M');
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 1,1,'Thăn bò Wagyu áp chảo','Món chính',1850000,'Thăn bò Wagyu áp chảo, dùng cùng khoai tây nghiền truffle, măng tây và sốt vang đỏ.','assets/images/steak.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=1);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 2,1,'Tôm hùm nướng bơ tỏi','Món chính',1650000,'Tôm hùm nướng bơ tỏi, ăn kèm rau củ theo mùa và sốt chanh vàng.','assets/images/seafood.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=2);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 3,1,'Gan ngỗng áp chảo','Khai vị',680000,'Gan ngỗng áp chảo với táo caramel, bánh brioche và sốt quả mọng.','assets/images/salad.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=3);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 4,1,'Salad burrata cà chua heirloom','Khai vị',320000,'Phô mai burrata mềm, cà chua heirloom, húng quế và dầu ô liu nguyên chất.','assets/images/salad.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=4);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 5,1,'Bánh chocolate fondant','Tráng miệng',250000,'Bánh chocolate nóng chảy, phục vụ cùng kem vanilla và quả mọng.','assets/images/dessert.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=5);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 6,1,'Mocktail lựu hương thảo','Đồ uống',180000,'Mocktail không cồn từ lựu, chanh vàng, soda và hương thảo tươi.','assets/images/drink.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=6);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 7,1,'Ức vịt sốt cam','Món chính',790000,'Ức vịt áp chảo da giòn, sốt cam, củ dền nướng và khoai tây nghiền.','assets/images/steak.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=7);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 8,1,'Trà hoa nhài thượng hạng','Đồ uống',150000,'Trà hoa nhài pha ấm, hương hoa thanh nhẹ, phục vụ nóng.','assets/images/drink.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=8);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 9,1,'Sò điệp Hokkaido áp chảo','Khai vị',590000,'Sò điệp Hokkaido áp chảo, kem súp lơ và sốt bơ chanh.','assets/images/salad.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=9);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 10,1,'Súp nấm truffle','Súp',290000,'Súp kem nấm mịn với dầu truffle và bánh mì giòn.','assets/images/salad.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=10);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 11,1,'Crème brûlée vanilla','Tráng miệng',230000,'Kem trứng vanilla với lớp đường caramel giòn, dùng kèm dâu tươi.','assets/images/dessert.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=11);
INSERT INTO tblDish (id,tblRestaurantid,name,type,basePrice,description,img) SELECT 12,1,'Cá tuyết nướng miso','Món chính',980000,'Cá tuyết ướp miso nướng, ăn kèm cải thìa và sốt gừng thanh nhẹ.','assets/images/seafood.jpg' WHERE NOT EXISTS (SELECT 1 FROM tblDish WHERE id=12);
INSERT INTO tblDishSize (tblDishid,tblSizeid,pricePercentage) SELECT d.id,s.id,100 FROM tblDish d JOIN tblSize s ON s.name='M' WHERE NOT EXISTS (SELECT 1 FROM tblDishSize ds WHERE ds.tblDishid=d.id AND ds.tblSizeid=s.id);
INSERT INTO tblCombo (name,price,description,tblRestaurantid) SELECT 'Signature Wagyu',2960000,'Thực đơn bốn món.',1 WHERE NOT EXISTS (SELECT 1 FROM tblCombo WHERE name='Signature Wagyu' AND tblRestaurantid=1);
